'use strict';
const ArtworkUI=(()=>{
  const A=FoldArtwork,el=id=>document.getElementById(id);let api,selected='main',editing=false,current=null,beforeControl=null,wheelStart=null,wheelTimer,uploading=false;
  const state=()=>api.state(),art=()=>A.normalize(state().artwork),part=()=>art().mode==='global'?'global':selected;
  function layer(data=art(),id=part()){return id==='global'?data.global:data.parts[id]}
  function setLayer(data,id,value){return id==='global'?{...data,global:value}:{...data,parts:{...data.parts,[id]:value}}}
  function flush(){if(!wheelStart)return;clearTimeout(wheelTimer);const start=wheelStart;wheelStart=null;api.commit(start)}
  function update(data,commit=true){if(commit)flush();api.change({...state(),artwork:data},commit)}
  function enable(value){editing=value;el('artTool').classList.toggle('selected',value);el('artTool').setAttribute('aria-pressed',String(value));el('drawing').classList.toggle('artwork-editing',value);api.refresh()}
  function select(id){const data=art();if(data.mode==='parts')selected=id;el('artworkPanel').open=true;sync();api.refresh()}
  function sync(){if(!api)return;const s=state(),t=api.template(),g=api.geometry();if(!g)return;const data=art(),regions=A.regions(t,s,g);if(!regions.some(r=>r.id===selected))selected=regions[0]?.id||'main';current={t,g,regions};
    const select=el('artPart'),ids=regions.map(r=>r.id).join('|');if(select.dataset.ids!==ids){select.innerHTML=regions.map(r=>`<option value="${r.id}">${A.esc(r.label)}</option>`).join('');select.dataset.ids=ids}select.value=selected;el('artPartField').hidden=data.mode!=='parts';document.querySelectorAll('[data-art-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artMode===data.mode)));
    const target=part(),value=layer(data,target),asset=value&&A.cache.get(value.asset),isColor=value?.type==='color';el('artTarget').textContent=target==='global'?'Whole dieline':regions.find(r=>r.id===target)?.label||target;el('artFileName').textContent=asset?asset.name:value?.asset?'Image unavailable — upload again':'Choose an image or drop it here';el('artPreview').hidden=!asset;if(asset)el('artPreview').src=asset.src;else el('artPreview').removeAttribute('src');el('artControls').hidden=!value||(!isColor&&!asset);el('removeArtwork').disabled=!value;el('removeArtwork').textContent=isColor?'Remove color':'Remove image';el('artUpload').disabled=uploading;el('artUpload').textContent=uploading?'Reading image…':asset?'Replace image':'Add image';el('copyGlobal').hidden=data.mode!=='parts'||!(data.global?.type==='color'||data.global?.asset);el('artEmpty').hidden=isColor||Boolean(asset);el('artEditHint').textContent=isColor?'Solid color · select any component to change its fill.':editing?'Background tool active · drag image to position, scroll to scale.':'Use Background tool to select a part and edit its background.';
    document.querySelectorAll('[data-art-source]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artSource===(isColor?'color':'image'))));el('artDrop').hidden=isColor;el('artColorControls').hidden=!isColor;el('artFit').closest('.field').hidden=isColor;for(const key of ['zoom','rotation'])el('art-'+key).closest('.art-adjust').hidden=isColor;el('art-x').closest('.field-grid').hidden=isColor;el('resetArtwork').hidden=isColor;
    if(isColor){el('artColor').value=value.color;if(document.activeElement!==el('artHex'))el('artHex').value=value.color;document.querySelectorAll('[data-art-swatch]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artSwatch===value.color)))}
    if(value){for(const key of ['zoom','opacity','rotation','x','y']){const input=el('art-'+key);if(document.activeElement!==input)input.value=Math.round(value[key]*100)/100;const number=el('art-number-'+key);if(number&&document.activeElement!==number)number.value=Math.round(value[key]*100)/100}el('artFit').value=value.fit}
    el('artTool').classList.toggle('selected',editing);el('artTool').setAttribute('aria-pressed',String(editing));
  }
  async function upload(file){if(!file)return;const template=api.template().id,target=part(),mode=art().mode;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){api.toast('Choose a PNG, JPG, or WebP image.');return}if(file.size>20*1024*1024){api.toast('Choose an image smaller than 20 MB.');return}uploading=true;sync();let bitmap;
    try{bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>60000000)throw new Error('Image exceeds 60 megapixels.');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/webp',.88),asset={id:crypto.randomUUID(),name:file.name,width:canvas.width,height:canvas.height,src};if(src.length>3500000)throw new Error('Image is too detailed. Try a smaller image.');const stored=await A.saveAssets([asset]);if(api.template().id!==template||art().mode!==mode){api.toast('Template or mode changed. Select the target and upload again.');return}update(setLayer(art(),target,A.setting(asset.id)));enable(true);api.toast(stored?'Background added · stored only on this machine':'Image added for this session. Export JSON to keep a backup.');}
    catch(error){api.toast('Could not load image: '+error.message)}finally{bitmap?.close();uploading=false;sync();el('artFile').value=''}
  }
  function boundsFor(id,data=state()){const t=api.template(),g=FoldGeometry.generate(t,data);return id==='global'?{x:0,y:0,w:g.bw,h:g.bh}:A.regions(t,data,g).find(r=>r.id===id)?.bounds}
  function drag(start,id,dx,dy){const data=A.normalize(start.artwork),value=layer(data,id),bounds=boundsFor(id,start);if(!value||value.type==='color'||!bounds)return;api.change({...start,artwork:setLayer(data,id,A.pan(value,bounds,dx,dy))},false)}
  function wheel(point,factor){const id=part(),data=art(),value=layer(data,id),bounds=boundsFor(id);if(!value||value.type==='color'||!bounds)return false;if(!wheelStart)wheelStart=state();update(setLayer(data,id,A.zoomAt(value,bounds,point,factor)),false);clearTimeout(wheelTimer);wheelTimer=setTimeout(flush,220);return true}
  function overlay(t,p,g,u){if(!editing)return '';const data=A.normalize(p.artwork),regions=data.mode==='global'?[{id:'global',label:'Whole dieline',points:[[0,0],[g.bw,0],[g.bw,g.bh],[0,g.bh]]}]:A.regions(t,p,g),chosen=data.mode==='global'?'global':selected;return `<defs><clipPath id="art-selection-clip"><path d="${A.outline(g)}" clip-rule="evenodd"/></clipPath></defs><g id="artSelection" clip-path="url(#art-selection-clip)">${regions.map(r=>{const value=layer(data,r.id);return `<path data-art-part="${r.id}" class="art-region ${r.id===chosen?'art-region-selected':''}" d="${A.path(r.points)}" tabindex="0" role="button" aria-label="Select background for ${r.label}" stroke-width="${u*1.3}" stroke-dasharray="${5*u} ${3*u}"><title>${r.label} · ${value?.type==='color'?'solid color':value?.asset?'drag to move image':'choose a color or image'}</title></path>`}).join('')}</g>`}
  function init(config){api=config;document.getElementById('foldGeometry').insertAdjacentHTML('beforebegin',`<details id="artworkPanel" open><summary>Background image <span class="art-local">LOCAL</span></summary><div class="art-mode" role="group" aria-label="Background mode"><button data-art-mode="global" aria-pressed="true">Whole dieline</button><button data-art-mode="parts" aria-pressed="false">By component</button></div><label class="field" id="artPartField" hidden>Component<select id="artPart" aria-label="Artwork component"></select></label><div id="artDrop" class="art-drop"><img id="artPreview" alt="Selected background preview" hidden><div><b id="artTarget">Whole dieline</b><span id="artFileName">Choose an image or drop it here</span></div><button type="button" id="artUpload">Add image</button><input id="artFile" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><p class="field-hint" id="artEmpty">PNG, JPG, WebP · up to 20 MB · processed locally.</p><button id="copyGlobal" hidden>Use whole-dieline image for every component</button><div id="artControls" hidden><label class="field">Image fit<select id="artFit"><option value="cover">Cover · crop to fill</option><option value="contain">Contain · show entire image</option><option value="stretch">Stretch · fill component</option></select></label>${[['zoom','Scale',10,1000,1,'%'],['opacity','Opacity',0,100,1,'%'],['rotation','Rotation',-180,180,1,'°']].map(([key,label,min,max,step,suffix])=>`<label class="art-adjust"><span>${label}</span><input id="art-${key}" type="range" min="${min}" max="${max}" step="${step}" aria-label="Image ${label.toLowerCase()}"><div><input id="art-number-${key}" type="number" min="${min}" max="${max}" step="any" aria-label="Image ${label.toLowerCase()} value"><span>${suffix}</span></div></label>`).join('')}<div class="field-grid"><label class="field">Horizontal offset (%)<div><input id="art-x" type="number" min="-500" max="500" step="0.1" aria-label="Image horizontal offset"></div></label><label class="field">Vertical offset (%)<div><input id="art-y" type="number" min="-500" max="500" step="0.1" aria-label="Image vertical offset"></div></label></div><div class="art-actions"><button id="resetArtwork">Reset position</button><button id="removeArtwork">Remove image</button></div></div><p id="artEditHint" class="field-hint"></p><p class="field-hint">Embedded in SVG and PDF printing. DXF contains cut/fold lines only. Artwork editing is shown in the 2D view.</p></details>`);
    document.querySelector('.paper-tools').insertAdjacentHTML('beforeend','<button id="artTool" aria-pressed="false" title="Select and move background images directly on the dieline">▧ Image tool</button>');
    el('artTool').textContent='▧ Background';el('artTool').title='Select components to edit their image or solid color';el('artworkPanel').querySelector('summary').firstChild.textContent='Background ';
    el('artDrop').insertAdjacentHTML('beforebegin',`<div class="art-source" role="group" aria-label="Background fill type"><button data-art-source="image" aria-pressed="true">▧ Image</button><button data-art-source="color" aria-pressed="false">● Solid color</button></div><div id="artColorControls" hidden><label class="field" for="artColor">Fill color</label><div class="art-color-entry"><input type="color" id="artColor" value="#c7d8b7" aria-label="Background color picker"><label for="artHex">HEX</label><input type="text" id="artHex" value="#c7d8b7" maxlength="7" spellcheck="false" aria-label="Background HEX color"></div><div class="art-swatches" aria-label="Quick colors">${[['#c7d8b7','Sage'],['#f3edda','Ivory'],['#c26e45','Terracotta'],['#d6b689','Kraft'],['#7499ad','Blue'],['#e7bdc3','Rose'],['#ffffff','White'],['#303b2c','Forest']].map(([color,name])=>`<button type="button" data-art-swatch="${color}" style="--swatch:${color}" aria-label="Use ${name} color" title="${name} · ${color}" aria-pressed="false"></button>`).join('')}</div></div>`);
    el('art-opacity').setAttribute('aria-label','Background opacity');el('art-number-opacity').setAttribute('aria-label','Background opacity value');el('copyGlobal').textContent='Apply whole background to every component';
    document.querySelectorAll('[data-art-source]').forEach(button=>button.onclick=()=>{const data=art(),id=part(),value=layer(data,id)||A.setting();update(setLayer(data,id,{...value,type:button.dataset.artSource}));enable(true);api.flat()});
    const colorValue=text=>{const match=String(text).trim().match(/^#?([a-fA-F0-9]{3}|[a-fA-F0-9]{6})$/);if(!match)return null;return '#'+(match[1].length===3?[...match[1]].map(c=>c+c).join(''):match[1]).toLowerCase()};
    for(const input of [el('artColor'),el('artHex')]){input.onfocus=()=>beforeControl=state();input.oninput=()=>{const color=colorValue(input.value);input.setCustomValidity(color?'':'Use #RRGGBB or #RGB.');if(!color)return;if(!beforeControl)beforeControl=state();const data=art(),id=part(),value=layer(data,id)||A.setting();update(setLayer(data,id,{...value,type:'color',color}),false)};input.onchange=()=>{if(beforeControl)api.commit(beforeControl);beforeControl=null;sync()};input.onblur=()=>{input.setCustomValidity('');if(input===el('artHex'))input.value=layer()?.color||'#c7d8b7';sync()}};
    document.querySelectorAll('[data-art-swatch]').forEach(button=>button.onclick=()=>{const data=art(),id=part(),value=layer(data,id)||A.setting();update(setLayer(data,id,{...value,type:'color',color:button.dataset.artSwatch}))});
    el('artTool').onclick=()=>{enable(!editing);if(editing){api.flat();el('artworkPanel').open=true;el('artworkPanel').scrollIntoView({behavior:'smooth',block:'nearest'})}};
    document.querySelectorAll('[data-art-mode]').forEach(button=>button.onclick=()=>{const data=art();update({...data,mode:button.dataset.artMode});enable(true);api.flat()});el('artPart').onchange=e=>{selected=e.target.value;enable(true);sync()};el('artUpload').onclick=()=>el('artFile').click();el('artFile').onchange=e=>upload(e.target.files[0]);
    el('artDrop').ondragover=e=>{e.preventDefault();el('artDrop').classList.add('drag-over')};el('artDrop').ondragleave=()=>el('artDrop').classList.remove('drag-over');el('artDrop').ondrop=e=>{e.preventDefault();el('artDrop').classList.remove('drag-over');upload(e.dataTransfer.files[0])};
    for(const key of ['zoom','opacity','rotation','x','y'])for(const input of [el('art-'+key),el('art-number-'+key)].filter(Boolean)){
      input.onfocus=()=>beforeControl=state();input.onpointerdown=()=>beforeControl=state();input.oninput=()=>{const data=art(),id=part(),value=layer(data,id),n=Number(input.value);if(!value||input.value===''||!Number.isFinite(n)||n<Number(input.min)||n>Number(input.max))return;if(!beforeControl)beforeControl=state();update(setLayer(data,id,{...value,[key]:n}),false)};input.onchange=()=>{if(beforeControl)api.commit(beforeControl);beforeControl=null;sync()};input.onblur=sync;input.addEventListener('wheel',e=>e.preventDefault(),{passive:false});
    }
    el('artFit').onchange=e=>{const data=art(),id=part(),value=layer(data,id);if(value)update(setLayer(data,id,{...value,fit:e.target.value}))};el('resetArtwork').onclick=()=>{const data=art(),id=part(),value=layer(data,id);if(value)update(setLayer(data,id,{...A.setting(value.asset),color:value.color}))};el('removeArtwork').onclick=()=>update(setLayer(art(),part(),null));el('copyGlobal').onclick=()=>{const data=art();if(!data.global)return;const parts={};for(const r of current.regions)parts[r.id]=data.global.type==='color'?{...data.global}:{...A.setting(data.global.asset),type:'image',color:data.global.color};update({...data,parts});api.toast('Background assigned independently to every component.')};
    A.loadAssets().then(()=>{sync();api.refresh()});
  }
  return{init,sync,overlay,select,drag,wheel,flush,setEditing:enable,editing:()=>editing,target:part,hasImage:id=>Boolean(layer(art(),id)?.type!=='color'&&A.cache.has(layer(art(),id)?.asset))};
})();
